package com.universalplatform.commercial;
import com.universalplatform.identity.*; import com.universalplatform.licensing.*; import com.universalplatform.security.TenantContext; import java.time.*; import java.util.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class QuotaService { private final TenantContext tenants; private final AuthorizationService auth; private final EntitlementLimitRepository limits; private final UsageCounterRepository counters; private final Clock clock=Clock.systemUTC(); QuotaService(TenantContext t,AuthorizationService a,EntitlementLimitRepository l,UsageCounterRepository c){tenants=t;auth=a;limits=l;counters=c;}
 @Transactional public UsageDecision consume(LimitKey key,long units){if(units<1)throw new IllegalArgumentException("units must be positive"); UUID tenant=tenants.requireTenantId(); Instant now=clock.instant(); Instant start=now.truncatedTo(java.time.temporal.ChronoUnit.DAYS); Instant end=start.plus(1,java.time.temporal.ChronoUnit.DAYS); EntitlementLimit limit=limits.findByTenantIdAndLimitKey(tenant,key).orElse(null); if(limit==null)return new UsageDecision(true,units,Long.MAX_VALUE); UsageCounter c=counters.findForUpdate(tenant,key,start).orElseGet(()->counters.save(new UsageCounter(new UsageCounterId(tenant,key,start),end))); long next=c.consumed()+units; if(next>limit.hardLimit())return new UsageDecision(false,c.consumed(),limit.hardLimit()); c.consume(units); counters.save(c); return new UsageDecision(true,next,limit.hardLimit()); }
 public record UsageDecision(boolean allowed,long consumed,long hardLimit){}
}
